/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: readProgressPaint, installDisjointRanges
 * Tests
 *   - paints native buffered progress, preserves seek gaps across player surfaces, and clears replaced media
 * @end-catalog */

import type { Locator, Page } from '@playwright/test';

import { catalogIds } from './fixtures/catalog';
import { expect, test } from './support/test';

/** Reads the painted track rather than relying only on store or inline state. */
const readProgressPaint = (locator: Locator, seek = true) => locator.evaluate((element, isSeek) => {
  const track = isSeek ? element.parentElement! : element;
  const style = getComputedStyle(track);
  const resolveColor = (variable: string) => {
    const probe = document.createElement('span');
    probe.style.color = `var(${variable})`;
    track.append(probe);
    const color = getComputedStyle(probe).color;
    probe.remove();
    return color;
  };
  return {
    buffered: style.getPropertyValue('--seek-buffered').trim(),
    played: style.getPropertyValue('--seek-progress').trim(),
    background: getComputedStyle(element).backgroundImage,
    accentColor: resolveColor('--color-accent'),
    bufferedColor: resolveColor('--color-text-subtle'),
    trackColor: resolveColor('--color-seek-track')
  };
}, seek);

/** Uses real media for loading, then controls only the range topology after seeking. */
const installDisjointRanges = async (page: Page) => page.locator('video:not([data-video-preview])').evaluate((media: HTMLVideoElement) => {
  const ranges = [[0, media.duration * 0.3], [media.duration * 0.6, media.duration * 0.8]];
  Object.defineProperty(media, 'buffered', {
    configurable: true,
    get: () => ({
      length: ranges.length,
      start: (index: number) => ranges[index]?.[0] ?? Number.NaN,
      end: (index: number) => ranges[index]?.[1] ?? Number.NaN
    })
  });
  media.currentTime = media.duration * 0.1;
  media.dispatchEvent(new Event('seeked'));
  media.dispatchEvent(new Event('progress'));
});

test('paints native buffered progress, preserves seek gaps across player surfaces, and clears replaced media', async ({ page }, testInfo) => {
  let releaseNextSource: () => void = () => undefined;
  const nextSourceGate = new Promise<void>((resolve) => { releaseNextSource = resolve; });
  // Hold the replacement before metadata so the old cache cannot hide behind a newly loaded stream.
  await page.route(`**/content/mediaTrack/stream/${catalogIds.secondTrack}`, async (route) => {
    await nextSourceGate;
    await route.fallback();
  });

  try {
    await page.setViewportSize({ width: 1_280, height: 800 });
    await page.goto(`/finitude/albums/${catalogIds.album}`);
    await page.getByRole('main').locator('header').getByRole('button', { name: 'Play', exact: true }).click();
    const player = page.getByRole('region', { name: 'Now playing' });
    const controls = player.getByRole('group', { name: 'Playback controls' });
    const slider = player.getByRole('slider', { name: 'Playback position' });
    const media = page.locator('video:not([data-video-preview])');
    await controls.getByRole('button', { name: 'Pause' }).click();
    await expect(slider).toBeEnabled();
    await expect.poll(() => media.evaluate((element: HTMLVideoElement) => element.buffered.length)).toBeGreaterThan(0);
    // This first assertion is driven by the browser's genuine TimeRanges and fixture bytes.
    await expect.poll(async () => (await readProgressPaint(slider)).buffered).toContain('linear-gradient');
    const nativeEnd = await media.evaluate((element: HTMLVideoElement) =>
      element.buffered.end(element.buffered.length - 1) / element.duration * 100
    );
    expect((await readProgressPaint(slider)).buffered).toContain(`${nativeEnd}%`);

    await installDisjointRanges(page);
    await expect.poll(async () => Number.parseFloat((await readProgressPaint(slider)).played)).toBeCloseTo(10, 4);
    const desktop = await readProgressPaint(slider);
    expect(desktop.buffered).toContain('0% 30%');
    expect(desktop.buffered).toContain('transparent 30%');
    expect(desktop.buffered).toContain('transparent 60%');
    expect(desktop.buffered).toContain('60% 80%');
    expect(desktop.background).toContain(desktop.accentColor);
    expect(desktop.background).toContain(desktop.bufferedColor);
    expect(desktop.background).toContain(desktop.trackColor);
    expect(desktop.background).toContain('rgba(0, 0, 0, 0) 30%');
    expect(desktop.background).toContain('rgba(0, 0, 0, 0) 60%');
    expect(new Set([desktop.accentColor, desktop.bufferedColor, desktop.trackColor]).size).toBe(3);
    await page.mouse.move(0, 0);
    await player.screenshot({ path: testInfo.outputPath('buffered-progress-desktop.png') });

    await slider.focus();
    await page.keyboard.press('ArrowRight');
    await expect.poll(() => media.evaluate((element: HTMLVideoElement) => element.currentTime)).toBeGreaterThan(1.5);
    expect((await readProgressPaint(slider)).buffered).toBe(desktop.buffered);
    const afterSeek = await readProgressPaint(slider);

    await page.setViewportSize({ width: 390, height: 844 });
    const compact = player.locator('[data-buffered-progress="compact"]');
    await expect(compact).toBeVisible();
    await expect(compact).toHaveAttribute('aria-hidden', 'true');
    const compactPaint = await readProgressPaint(compact, false);
    expect(compactPaint.buffered).toBe(afterSeek.buffered);
    expect(compactPaint.played).toBe(afterSeek.played);
    expect(compactPaint.background).toContain(compactPaint.bufferedColor);
    await player.screenshot({ path: testInfo.outputPath('buffered-progress-mobile-compact.png') });

    await page.getByRole('button', { name: 'Open Now Playing: First Light' }).click();
    const expanded = page.getByRole('dialog', { name: 'First Light' });
    const expandedSlider = expanded.getByRole('slider', { name: 'Playback position' });
    await expect(expandedSlider).toBeVisible();
    const expandedPaint = await readProgressPaint(expandedSlider);
    expect(expandedPaint.buffered).toBe(afterSeek.buffered);
    expect(expandedPaint.played).toBe(afterSeek.played);
    expect(expandedPaint.background).toContain(expandedPaint.bufferedColor);
    await expanded.screenshot({ path: testInfo.outputPath('buffered-progress-mobile-expanded.png') });
    await expanded.getByRole('button', { name: 'Close expanded player' }).click();

    await page.setViewportSize({ width: 1_280, height: 800 });
    await controls.getByRole('button', { name: 'Next MediaTrack' }).click();
    await expect(player).toContainText('Night Window');
    await expect(slider).toBeDisabled();
    await expect.poll(async () => (await readProgressPaint(slider)).buffered).toBe('none');
    expect((await readProgressPaint(slider)).played).toBe('0%');
    await media.evaluate((element) => Reflect.deleteProperty(element, 'buffered'));
    releaseNextSource();
    await expect(slider).toBeEnabled();
    await expect.poll(() => media.evaluate((element: HTMLVideoElement) => element.buffered.length)).toBeGreaterThan(0);
    await expect.poll(async () => (await readProgressPaint(slider)).buffered).toContain('linear-gradient');
  } finally {
    releaseNextSource();
  }
});
